import{_ as a}from"./chunks/daily-2026-08-10-governed-input-admission-boundary-figure.DQHTuyyG.js";import{_ as n,C as i,o,c as d,E as r,a2 as s}from"./chunks/framework.Cm6XCzck.js";const y=JSON.parse('{"title":"可恢复数字员工需要受治理的输入准入边界","description":"","frontmatter":{"title":"可恢复数字员工需要受治理的输入准入边界","date":"2026-08-10","column":"digital-employee","category":"daily","summary":"可恢复数字员工应把迟到的操作员输入视为带持久 Occurrence Identity、策略校验与消费证据的准入事件，同时把外部副作用留在独立的幂等或事务边界内。","sources":["research/analysis/Q-20260810-01-governed-input-admission.md","research/reading/Q-20260810-01-durable-runstate-pending-input.md"],"item_id":"Q-20260810-01","lifecycle":"Published","source_research_object":"research/analysis/Q-20260810-01-governed-input-admission.md","source_reading_result":"research/reading/Q-20260810-01-durable-runstate-pending-input.md","cover":"/assets/covers/daily-2026-08-10-governed-input-admission-boundary.webp","visualization":"/assets/covers/daily-2026-08-10-governed-input-admission-boundary-figure.svg","visualization_decision":"Required — dedicated editorial Article Cover passes Cover Gate; explanatory Article Figure retained separately","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"outline":"deep"},"headers":[],"relativePath":"zh/digital-employee/2026-08-10-governed-input-admission-boundary.md","filePath":"zh/digital-employee/2026-08-10-governed-input-admission-boundary.md","lastUpdated":1786455299000}'),c={name:"zh/digital-employee/2026-08-10-governed-input-admission-boundary.md"};function p(l,e,u,h,m,g){const t=i("ArticleCover");return o(),d("div",null,[r(t,{image:"/assets/covers/daily-2026-08-10-governed-input-admission-boundary.webp",kicker:"数字员工 · 每日研究",title:"可恢复数字员工需要受治理的输入准入边界",summary:"可恢复数字员工应把迟到的操作员输入视为带持久 Occurrence Identity、策略校验与消费证据的准入事件，同时把外部副作用留在独立的幂等或事务边界内。",version:"Q-20260810-01",status:"Daily Runtime V5 · 2026-08-10",languageHref:"/en/digital-employee/2026-08-10-governed-input-admission-boundary",languageLabel:"English"}),e[0]||(e[0]=s('<h1 id="可恢复数字员工需要受治理的输入准入边界" tabindex="-1">可恢复数字员工需要受治理的输入准入边界 <a class="header-anchor" href="#可恢复数字员工需要受治理的输入准入边界" aria-label="Permalink to &quot;可恢复数字员工需要受治理的输入准入边界&quot;">​</a></h1><p>一个能够暂停、等待人工输入、跨进程恢复并继续调用工具的数字员工，仅仅保存聊天记录是不够的。系统还必须明确：一条新收到的输入，究竟在什么时刻开始成为本次运行的权威输入。</p><h2 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to &quot;摘要&quot;">​</a></h2><p><strong>核心判断是：迟到的操作员输入应被建模为“准入事件”，而不是直接追加进对话历史。</strong> 同一次输入必须拥有可持久识别的 Occurrence Identity，在进入下一次模型调用前经过策略校验，并能够留下“已收到、已准入、已消费”分别对应的证据。</p><p>本次已完成 Reading Result 所检查的 OpenAI Agents Python 合并实现，为 SDK 自己拥有的 RunState 范围内提供了具体工程证据。但它并不证明任意外部工具副作用具有分布式 Exactly-once 语义，因此业务动作仍需要独立的幂等键、事务边界或补偿策略。</p><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to &quot;来源&quot;">​</a></h2><p>Production 只消费当日 Research Object <code>Q-20260810-01</code>，并仅使用已完成 Reading Result 来核对引用与证据边界。主要一手证据来自 OpenAI Agents Python 的 Issue #4323、已合并 PR #4325 与提交 <code>7bf73afa47ac48c1efb599d0b1505cee994e74f5</code>。</p><ul><li>Issue：<a href="https://github.com/openai/openai-agents-python/issues/4323" target="_blank" rel="noreferrer">https://github.com/openai/openai-agents-python/issues/4323</a></li><li>已合并 PR：<a href="https://github.com/openai/openai-agents-python/pull/4325" target="_blank" rel="noreferrer">https://github.com/openai/openai-agents-python/pull/4325</a></li><li>实现提交：<a href="https://github.com/openai/openai-agents-python/commit/7bf73afa47ac48c1efb599d0b1505cee994e74f5" target="_blank" rel="noreferrer">https://github.com/openai/openai-agents-python/commit/7bf73afa47ac48c1efb599d0b1505cee994e74f5</a></li></ul><h2 id="观察" tabindex="-1">观察 <a class="header-anchor" href="#观察" aria-label="Permalink to &quot;观察&quot;">​</a></h2><p>仓库实现把 Pending Input 保持在当前模型/工具执行之外，直到下一次模型调用前的准入边界。Reading Result 记录了几个关键机制：Pending Input 能随 <code>RunState</code> 序列化保存；它带有生成的 Occurrence Identifier；只有当未完成工作走到合适的恢复点后，输入才会被准入；Input Guardrail 在下一次模型调用前执行；校验失败的输入不会被静默消费，而是保持可恢复状态。</p><p>证据同样给出了清晰的所有权边界。SDK 可以在自身掌控的会话与准入账本中维护 Exactly-once 语义，但这不等于任意外部工具在崩溃、重试、跨主机执行时也会 Exactly-once。</p><p><img src="'+a+'" alt="输入准入生命周期图"></p><p><em>图 1：迟到输入在恢复边界前保持待准入状态，经过策略校验后才进入下一次模型调用。来源：Research Center 基于文中引用的一手资料综合绘制。</em></p><h2 id="比较" tabindex="-1">比较 <a class="header-anchor" href="#比较" aria-label="Permalink to &quot;比较&quot;">​</a></h2><table tabindex="0"><thead><tr><th>输入模型</th><th>持久 Occurrence Identity</th><th>准入点</th><th>策略校验</th><th>消费证据</th><th>外部副作用保证</th></tr></thead><tbody><tr><td>直接追加聊天/历史</td><td>通常没有</td><td>隐式</td><td>容易与执行过程混在一起</td><td>难以区分“收到”和“已使用”</td><td>不提供</td></tr><tr><td>复用 Session 开新 Run</td><td>新 Run 边界</td><td>新 Run 开始</td><td>由新 Run 流程处理</td><td>Session 历史可持久，但运行身份已经变化</td><td>不提供</td></tr><tr><td>可恢复 <code>RunState</code> 的 Durable Pending Input</td><td>显式 <code>input_id</code></td><td>未完成工作结束后的下一次模型调用前</td><td>准入前执行 Guardrail</td><td>Pending/current-step 与已接纳进度被 Checkpoint</td><td>仅 SDK 自有范围</td></tr><tr><td>受治理的数字员工 Input Admission Ledger</td><td>Research Center 工程方案</td><td>显式状态迁移</td><td>把策略决定记录为证据</td><td>Received → Pending → Admitted/Rejected → Consumed</td><td>需要独立 Tool 幂等/事务键</td></tr></tbody></table><p>前三行对应已记录的文档或实现机制；最后一行是从 Research Object 推导出的工程设计建议，并不是在声称该 SDK 已经实现完整企业级 Admission Ledger。</p><h2 id="讨论" tabindex="-1">讨论 <a class="header-anchor" href="#讨论" aria-label="Permalink to &quot;讨论&quot;">​</a></h2><p>内容相同，不代表发生的是同一次输入。两条完全相同的操作员消息可能是两个合法动作；同一个 Occurrence 如果在恢复时被重复消费，则必须被识别为重放。因此，持久 Occurrence Identity 比单纯比较输入内容更重要。</p><p>准入边界还决定了策略应该放在哪里。如果 Guardrail 在输入已经修改权威运行状态之后才执行，那么恢复语义会变得模糊：这条输入究竟是“已经接受后又被拒绝”，还是“从未接受”？受治理的运行时应把这个迁移明确化，并留下追加式证据。</p><p>最后，恢复正确性与副作用正确性必须分开。Checkpoint 可以避免模型层轻易重放一个已经完成的工具调用，但如果宿主在本地状态提交与远端业务提交之间崩溃，外部系统仍需要自己的幂等键、事务标识或补偿机制。</p><h2 id="工程影响" tabindex="-1">工程影响 <a class="header-anchor" href="#工程影响" aria-label="Permalink to &quot;工程影响&quot;">​</a></h2><p>对数字员工运行时，应建立 Input Admission Ledger，至少记录 Occurrence ID、received-at、admitted-at、Guardrail Decision、consuming run/step 与最终 disposition，并显式区分 <code>Received</code>、<code>Pending Admission</code>、<code>Admitted</code>、<code>Rejected/Recoverable</code>、<code>Consumed</code>。</p><p>对 CodeFlowMu，Worker/Run Checkpoint 与操作员输入应先作为两类独立持久状态存在，直到发生明确的 Admission Transition。对可能在 Resume 后重试的外部副作用工具，可将 Admission Occurrence ID 传播到 Tool Call Idempotency Key，并把准入与 Checkpoint 事件暴露到运行时间线。</p><p>对 TMPA，这个实现可以作为 Custody / Admission 语义的工程证据，但单个 SDK 实现不足以直接推动协议层变更。</p><h2 id="边界与不确定性" tabindex="-1">边界与不确定性 <a class="header-anchor" href="#边界与不确定性" aria-label="Permalink to &quot;边界与不确定性&quot;">​</a></h2><p>现有证据证明的是 OpenAI Agents Python 中的设计意图、合并实现和回归覆盖，不证明任意存储故障、跨主机竞争或分布式系统中的 Exactly-once。这个机制也不是可以向正在执行中的模型/工具调用并发注入消息的线程安全通道，任意对话历史替换或压缩同样不在本特性范围内。</p><h2 id="后续工作" tabindex="-1">后续工作 <a class="header-anchor" href="#后续工作" aria-label="Permalink to &quot;后续工作&quot;">​</a></h2><p>产品级数字员工运行时应重点测试 Receipt、Admission、Checkpoint Persistence 与 External Side Effect 之间的崩溃点，并定义被撤回、替代或过期的 Pending Input 如何在不擦除审计历史的前提下表示。同时需要决定 Occurrence Identity 是传播到所有下游工具，还是仅传播到具有外部副作用的调用。</p><h2 id="可视化说明" tabindex="-1">可视化说明 <a class="header-anchor" href="#可视化说明" aria-label="Permalink to &quot;可视化说明&quot;">​</a></h2><p>题图位于文章头部，以受控闸门表现迟到输入的保存、校验与准入边界；嵌入“观察”部分的解释图用于精确说明输入生命周期。两种视觉角色使用不同资产；未使用厂商原图，也未构造无来源数值。</p><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ol><li>OpenAI <code>openai-agents-python</code> Issue #4323，Durable Input 需求与验收场景：<a href="https://github.com/openai/openai-agents-python/issues/4323" target="_blank" rel="noreferrer">https://github.com/openai/openai-agents-python/issues/4323</a></li><li>OpenAI <code>openai-agents-python</code> PR #4325，已合并 Durable Pending Input 实现：<a href="https://github.com/openai/openai-agents-python/pull/4325" target="_blank" rel="noreferrer">https://github.com/openai/openai-agents-python/pull/4325</a></li><li>OpenAI <code>openai-agents-python</code> 提交 <code>7bf73afa47ac48c1efb599d0b1505cee994e74f5</code>：<a href="https://github.com/openai/openai-agents-python/commit/7bf73afa47ac48c1efb599d0b1505cee994e74f5" target="_blank" rel="noreferrer">https://github.com/openai/openai-agents-python/commit/7bf73afa47ac48c1efb599d0b1505cee994e74f5</a></li><li>Research Center Research Object：<code>research/analysis/Q-20260810-01-governed-input-admission.md</code></li><li>Research Center Reading Result：<code>research/reading/Q-20260810-01-durable-runstate-pending-input.md</code></li></ol><blockquote><p>Editing status：已发布。事实边界、SDK 语义范围、外部副作用边界、中英文结构与证据可追溯性均已检查。</p></blockquote>',33))])}const _=n(c,[["render",p]]);export{y as __pageData,_ as default};
